"""Typed model definitions, module records and value semantics.

The offline profile describes every model through plain JSON.  This module
turns those descriptions into the small type algebra used by the rest of the
toolkit: named declarations, transparent aliases, and the value rules that
keep booleans, integers, arrays and objects distinguishable.
"""


class Type(object):
    """Base class of every Eywa model type."""

    kind = 'type'

    def inner(self):
        """Resolve alias declarations to the underlying type."""
        type = self
        while isinstance(type, Alias):
            type = type.target
        return type

    def declaration(self):
        """Name of the C declaration this type needs, if any."""
        return None


class Void(Type):
    """No value at all; only permitted directly as a module result."""

    kind = 'void'


class Bool(Type):
    """Boolean value."""

    kind = 'bool'


class Char(Type):
    """A single Latin-1 character."""

    kind = 'char'


class Int(Type):
    """Unsigned integer with a fixed bit width."""

    kind = 'int'

    def __init__(self, bits):
        self.bits = int(bits)

    def width(self):
        """Smallest of 1, 2, 4 or 8 bytes that holds every value."""
        for size in (1, 2, 4, 8):
            if self.bits <= size * 8:
                return size
        return 8

    def modulus(self):
        return 1 << self.bits


class String(Type):
    """Bounded Latin-1 C string."""

    kind = 'string'

    def __init__(self, maxsize):
        self.maxsize = int(maxsize)


class Enum(Type):
    """A choice among a fixed list of value names."""

    kind = 'enum'

    def __init__(self, name, values):
        self.name = name
        self.values = list(values)


class Array(Type):
    """Ordered fixed-length list of elements."""

    kind = 'array'

    def __init__(self, element, size):
        self.element = element
        self.size = int(size)


class Struct(Type):
    """An ordered record of named fields."""

    kind = 'struct'

    def __init__(self, name, fields):
        self.name = name
        self.fields = list(fields)

    def field(self, name):
        for field_name, field_type in self.fields:
            if field_name == name:
                return field_type
        raise KeyError(name)


class Alias(Type):
    """A transparent alias that keeps its declaration name."""

    kind = 'alias'

    def __init__(self, name, target):
        self.name = name
        self.target = target

    def declaration(self):
        return self.name


class TypeEnv(object):
    """Lazily builds the named type declarations of a campaign."""

    def __init__(self, definitions):
        self.definitions = {}
        for definition in definitions or ():
            self.definitions[definition['name']] = definition
        self.cache = {}
        self.building = set()

    def get(self, name):
        """Return the declared type called `name`."""
        if name in self.cache:
            return self.cache[name]
        definition = self.definitions.get(name)
        if definition is None:
            if name == 'void':
                type = Void()
            else:
                raise ValueError('unknown type: ' + str(name))
        else:
            if name in self.building:
                raise ValueError('cyclic type: ' + str(name))
            self.building.add(name)
            kind = definition['kind']
            if kind == 'bool':
                type = Bool()
            elif kind == 'char':
                type = Char()
            elif kind == 'void':
                type = Void()
            elif kind == 'int':
                type = Int(definition['bits'])
            elif kind == 'string':
                type = String(definition['maxsize'])
            elif kind == 'enum':
                type = Enum(definition['name'], definition['values'])
            elif kind == 'array':
                type = Array(self.get(definition['element']), definition['size'])
            elif kind == 'struct':
                type = Struct(definition['name'],
                              [(field[0], self.get(field[1]))
                               for field in definition['fields']])
            elif kind == 'alias':
                type = Alias(definition['name'], self.get(definition['target']))
            else:
                raise ValueError('unknown kind: ' + str(kind))
            self.building.discard(name)
        self.cache[name] = type
        return type


class Module(object):
    """A model module: ordered parameters, one result, one predicate."""

    __slots__ = ('name', 'params', 'result', 'requires', 'raw_requires')

    def __init__(self, name, params, result, requires, raw_requires=None):
        self.name = name
        self.params = params
        self.result = result
        self.requires = requires
        self.raw_requires = raw_requires

    def scope(self):
        """Variable name to type mapping visible to this module."""
        return dict((param[0], param[1]) for param in self.params)

    def result_type(self):
        return self.result[1].inner()


def constant_value(type, value):
    """Build the internal value of a typed constant."""
    type = type.inner()
    kind = type.kind
    if kind == 'bool':
        return bool(value)
    if kind == 'int':
        return int(value)
    if kind == 'char' or kind == 'string' or kind == 'enum':
        return value
    if kind == 'array':
        return [constant_value(type.element, item) for item in value]
    if kind == 'struct':
        return dict((name, constant_value(field_type, value[name]))
                    for name, field_type in type.fields)
    raise ValueError('constant of unsupported type')


def values_equal(type, left, right):
    """Deep comparison of two values of the same underlying type."""
    type = type.inner()
    kind = type.kind
    if kind == 'bool':
        return left is right or (left == right and isinstance(left, bool)
                                 and isinstance(right, bool))
    if kind == 'int':
        return left == right and not isinstance(left, bool) \
            and not isinstance(right, bool)
    if kind == 'char' or kind == 'string' or kind == 'enum':
        return left == right
    if kind == 'array':
        if len(left) != len(right):
            return False
        for one, two in zip(left, right):
            if not values_equal(type.element, one, two):
                return False
        return True
    if kind == 'struct':
        for name, field_type in type.fields:
            if not values_equal(field_type, left[name], right[name]):
                return False
        return True
    return left == right


def canonical_value(type, value):
    """Hashable identity of a value that keeps its JSON type identity."""
    type = type.inner()
    kind = type.kind
    if kind == 'bool':
        return ('b', value)
    if kind == 'int':
        return ('i', value)
    if kind == 'char':
        return ('c', value)
    if kind == 'string':
        return ('s', value)
    if kind == 'enum':
        return ('e', value)
    if kind == 'array':
        return ('a', tuple(canonical_value(type.element, item) for item in value))
    if kind == 'struct':
        return ('t', tuple((name, canonical_value(field_type, value[name]))
                           for name, field_type in type.fields))
    return ('v', repr(value))
