"""Module dependency composition.

Call edges make the callee a prerequisite of the caller; pipe edges make the
filter a prerequisite of the module it is attached to.  A plan lists the root
plus every transitive prerequisite, ordered so that prerequisites precede
dependents.  Whenever several modules are eligible at the same time the
lexicographically smallest name is taken first.
"""

import heapq


class DependencyGraph(object):
    """The module dependency graph of a campaign."""

    def __init__(self):
        self.calls = []
        self.pipes = []
        self.callees = {}
        self.filters = {}

    def add_call(self, caller, callee):
        """Record that `caller` depends on `callee`."""
        if (caller, callee) in self.calls:
            return
        self.calls.append((caller, callee))
        self.callees.setdefault(caller, []).append(callee)

    def add_pipe(self, target, filter_module):
        """Record that `filter_module` guards `target`."""
        self.pipes.append((target, filter_module))
        self.filters.setdefault(target, []).append(filter_module)

    def prerequisites(self, root):
        """Every module the root needs, including the root itself."""
        needed = set([root])
        pending = [root]
        while pending:
            current = pending.pop()
            for callee in self.callees.get(current, ()):
                if callee not in needed:
                    needed.add(callee)
                    pending.append(callee)
            for filter_module in self.filters.get(current, ()):
                if filter_module not in needed:
                    needed.add(filter_module)
                    pending.append(filter_module)
        return needed

    def compile_order(self, root):
        """Order the root and its prerequisites for compilation."""
        needed = self.prerequisites(root)
        dependents = {}
        indegree = dict((name, 0) for name in needed)
        for caller, callee in self.calls:
            if caller in needed and callee in needed:
                dependents.setdefault(callee, set()).add(caller)
                indegree[caller] += 1
        for target, filter_module in self.pipes:
            if target in needed and filter_module in needed:
                dependents.setdefault(filter_module, set()).add(target)
                indegree[target] += 1
        ready = [name for name in needed if indegree[name] == 0]
        heapq.heapify(ready)
        ordered = []
        while ready:
            name = heapq.heappop(ready)
            ordered.append(name)
            for dependent in sorted(dependents.get(name, ())):
                indegree[dependent] -= 1
                if indegree[dependent] == 0:
                    heapq.heappush(ready, dependent)
        if len(ordered) != len(needed):
            raise ValueError('cyclic module dependencies')
        return ordered
