"""Strict binary symbolic-test transport.

Recorded witnesses arrive as standard base64 without whitespace.  The binary
payload is a KTEST version 3 container: the ``KTEST`` magic, a big-endian
version, the argument blobs, the symbolic-argv bookkeeping words and finally
the object name/data pairs.  Every blob is a length word followed by exactly
that many bytes and nothing may follow the last object.
"""

import base64
import binascii

MAGIC = b'KTEST'
VERSION = 3
MAX_ARGUMENTS = 64
MAX_ARGUMENT_BYTES = 256


class InvalidTest(Exception):
    """Raised for any transport, inventory or leaf level defect."""


def _canonical_name(raw):
    """True when the object name is `x` plus a canonical decimal number."""
    if not raw.startswith(b'x'):
        return False
    digits = raw[1:]
    if not digits:
        return False
    if not digits.isdigit():
        return False
    if digits[0:1] == b'0':
        return len(digits) == 1
    return True


def decode(payload):
    """Decode a base64 KTEST payload into a mapping of object name to bytes."""
    if isinstance(payload, str):
        try:
            encoded = payload.encode('ascii')
        except UnicodeEncodeError:
            raise InvalidTest('payload is not base64')
    elif isinstance(payload, (bytes, bytearray)):
        encoded = bytes(payload)
    else:
        raise InvalidTest('payload is not base64')
    try:
        raw = base64.b64decode(encoded, validate=True)
    except (binascii.Error, ValueError):
        raise InvalidTest('payload is not base64')

    size = len(raw)
    if size < 5 or raw[:5] != MAGIC:
        raise InvalidTest('bad magic')
    position = 5

    def word():
        nonlocal position
        if position + 4 > size:
            raise InvalidTest('truncated header')
        value = int.from_bytes(raw[position:position + 4], 'big')
        position += 4
        return value

    def blob():
        nonlocal position
        length = word()
        if length > size - position:
            raise InvalidTest('truncated blob')
        data = raw[position:position + length]
        position += length
        return data

    if word() != VERSION:
        raise InvalidTest('unsupported version')
    arguments = word()
    if arguments > MAX_ARGUMENTS:
        raise InvalidTest('too many arguments')
    for _ in range(arguments):
        if len(blob()) > MAX_ARGUMENT_BYTES:
            raise InvalidTest('argument too large')
    word()  # symbolic argv count, bookkeeping only
    word()  # symbolic argv length, bookkeeping only
    count = word()
    if count > size:
        raise InvalidTest('too many objects')
    objects = {}
    for _ in range(count):
        name = blob()
        data = blob()
        if not _canonical_name(name):
            raise InvalidTest('malformed object name')
        key = name.decode('ascii')
        if key in objects:
            raise InvalidTest('duplicate object')
        objects[key] = data
    if position != size:
        raise InvalidTest('trailing bytes')
    return objects


def check_inventory(objects, expected):
    """Verify that the recorded objects are exactly the expected ones."""
    if len(objects) != len(expected):
        raise InvalidTest('object inventory mismatch')
    for name, width in expected.items():
        if name not in objects:
            raise InvalidTest('missing object ' + name)
        if len(objects[name]) != width:
            raise InvalidTest('wrong width for ' + name)
    for name in objects:
        if name not in expected:
            raise InvalidTest('unexpected object ' + name)


def values(objects):
    """Interpret every recorded object as a little-endian unsigned integer."""
    result = {}
    for name, data in objects.items():
        result[name] = int.from_bytes(data, 'little')
    return result
