"""Stateful replay preparation.

A machine is a set of states, an initial state and guarded transitions.  A
usable preparation is a path of enabled transitions from the initial state to
the recovered desired state.  Among all such paths the preparation minimises
the total cost, then the number of commands, then the command sequence in
lexicographic order.  Guards are evaluated on the recovered entry inputs, so
the desired state is the one the transition predicates see.
"""

import heapq


class Machine(object):
    """The state machine of a campaign."""

    __slots__ = ('states', 'initial', 'state_param', 'message_param',
                 'transitions')

    def __init__(self, spec):
        self.states = list(spec['states'])
        self.initial = spec['initial']
        self.state_param = spec['state_param']
        self.message_param = spec['message_param']
        self.transitions = list(spec['transitions'])


def group_guards(guards):
    """Group transition guards so that identical ones are evaluated once.

    `guards` holds the raw guard expression of every transition, or None.
    The result maps a transition index to a group index and lists the
    distinct guard expressions.
    """
    groups = []
    lookup = {}
    group_of = []
    for guard in guards:
        if guard is None:
            group_of.append(None)
            continue
        key = _canonical(guard)
        index = lookup.get(key)
        if index is None:
            index = len(groups)
            lookup[key] = index
            groups.append(guard)
        group_of.append(index)
    return group_of, groups


def _canonical(node):
    """A stable identity for a guard expression."""
    if isinstance(node, list):
        return ('[',) + tuple(_canonical(item) for item in node)
    if isinstance(node, dict):
        return ('{',) + tuple(sorted((key, _canonical(value))
                                     for key, value in node.items()))
    return (type(node).__name__, node)


class Preparer(object):
    """Computes minimum cost state preparations for one entry."""

    def __init__(self, machine, group_of, group_functions):
        self.machine = machine
        self.group_of = group_of
        self.group_functions = group_functions
        self.out_edges = {}
        self.in_edges = {}
        for index, transition in enumerate(machine.transitions):
            source = transition['from']
            target = transition['to']
            weight = transition['cost']
            command = transition['command']
            self.out_edges.setdefault(source, []).append(
                (target, weight, command, index))
            self.in_edges.setdefault(target, []).append(
                (source, weight, command, index))
        self._enabled_cache = {}
        self._path_cache = {}

    def signature(self, context):
        """Evaluate every distinct guard once and return the outcome."""
        return tuple(bool(function(context))
                     for function in self.group_functions)

    def enabled(self, signature):
        """The set of transition indices enabled by a guard signature."""
        found = self._enabled_cache.get(signature)
        if found is None:
            found = set()
            for index, group in enumerate(self.group_of):
                if group is None or signature[group]:
                    found.add(index)
            self._enabled_cache[signature] = found
        return found

    def prepare(self, desired, signature):
        """Return (commands, cost) for a desired state, or None."""
        key = (desired, signature)
        if key in self._path_cache:
            return self._path_cache[key]
        result = self._compute(desired, self.enabled(signature))
        self._path_cache[key] = result
        return result

    def _compute(self, desired, enabled):
        if desired not in self.machine.states:
            return None
        distance = {}
        steps = {}
        distance[desired] = 0
        steps[desired] = 0
        heap = [(0, 0, desired)]
        while heap:
            cost, count, state = heapq.heappop(heap)
            if distance.get(state) != cost or steps.get(state) != count:
                continue
            for source, weight, _command, index in self.in_edges.get(state, ()):
                if index not in enabled:
                    continue
                new_cost = cost + weight
                new_count = count + 1
                old_cost = distance.get(source)
                if (old_cost is None or new_cost < old_cost
                        or (new_cost == old_cost
                            and new_count < steps.get(source, 0))):
                    distance[source] = new_cost
                    steps[source] = new_count
                    heapq.heappush(heap, (new_cost, new_count, source))
        if self.machine.initial not in distance:
            return None
        commands = []
        state = self.machine.initial
        while state != desired:
            best = None
            for target, weight, command, index in self.out_edges.get(state, ()):
                if index not in enabled:
                    continue
                if distance.get(target, -1) + weight != distance[state]:
                    continue
                if steps.get(target, -1) + 1 != steps[state]:
                    continue
                if best is None or command < best[0]:
                    best = (command, target)
            if best is None:
                return None
            commands.append(best[0])
            state = best[1]
        return (commands, distance[self.machine.initial])
