"""Corpus identity for recorded witnesses.

A corpus identity is the pair of an entry and its recovered input values.  The
model result, the bytes behind a string terminator, transport arguments,
object order and preparation metadata are all excluded.  Values keep their
JSON type identity, so an empty array never collides with an empty object
and a boolean never collides with an integer.
"""

from .ast import canonical_value


def corpus_key(entry, params, values):
    """The identity of one recovered input vector."""
    identity = []
    for name, type in params:
        identity.append((name, canonical_value(type, values[name])))
    return (entry, tuple(identity))


class Corpus(object):
    """Collects corpus cases in first usable witness order."""

    def __init__(self):
        self.cases = []
        self.index = {}

    def lookup(self, key):
        """Return the corpus index of an identity, or None."""
        return self.index.get(key)

    def add(self, key, entry, inputs, cost, commands, witness):
        """Register a new corpus case and return its index."""
        position = len(self.cases)
        self.cases.append({
            'entry': entry,
            'inputs': inputs,
            'cost': cost,
            'commands': list(commands),
            'witnesses': [witness],
        })
        self.index[key] = position
        return position

    def witness(self, position, witness):
        """Record another usable witness of an existing corpus case."""
        self.cases[position]['witnesses'].append(witness)

    def result(self):
        return self.cases
