        for (param_name, _param_type), node in zip(plan.module.params,
                                                   plan.roots):
            recovered[param_name] = recover(node, values)
        model_result = None
        if plan.result is not None:
            model_result = recover(plan.result, values)
    except LeafError:
        return {'status': 'INVALID_TEST'}

    accepted = True
    if plan.flag is not None:
        expected_flag = 1 if not accepted else 0
        if values[plan.flag] != expected_flag:
            return {'status': 'INVALID_TEST'}

    module = plan.module
    if module.requires is not None and not module.requires(recovered):
        return {'status': 'FILTERED'}
    if not _filters_accept(entry, recovered, modules, grouped):
        return {'status': 'FILTERED'}

    if machine is None:
        commands = []
        cost = 0
    else:
        preparer = preparers[entry]
        desired = recovered[machine.state_param]
        message = recovered[machine.message_param]
        signature = preparer.signature(recovered)
        preparation = preparer.prepare(desired, signature)
        if preparation is None:
            return {'status': 'UNREACHABLE'}
        commands = list(preparation[0]) + [message]
        cost = preparation[1]

