#!/usr/bin/env python3
"""Local mirror of the public checker without the kill/setpgid overlay."""
import json, math, subprocess, sys, time
from pathlib import Path

def pairs(items):
    value = {}
    for key, item in items:
        if key in value:
            raise ValueError("duplicate key")
        value[key] = item
    return value

def strict_json(raw):
    def bad_constant(value):
        raise ValueError("non-finite number")
    def finite_float(value):
        number = float(value)
        if not math.isfinite(number):
            raise ValueError("non-finite number")
        return number
    return json.loads(raw.decode("utf-8"), object_pairs_hook=pairs,
                      parse_constant=bad_constant, parse_float=finite_float)

def run_child(candidate, data, timeout=120):
    env = {"PATH": "/usr/local/bin:/usr/bin:/bin", "LANG": "C", "LC_ALL": "C",
           "HOME": "/workspace", "TMPDIR": "/workspace/tmp",
           "PYTHONDONTWRITEBYTECODE": "1", "PYTHONUNBUFFERED": "1",
           "PYTHONHASHSEED": "0"}
    started = time.monotonic()
    child = subprocess.Popen([sys.executable, "-I", "-B", str(candidate)],
                             stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                             stderr=subprocess.PIPE, close_fds=True, env=env)
    out, err = child.communicate(data, timeout=timeout)
    if child.returncode != 0:
        raise ValueError("candidate exited " + str(child.returncode) + " stderr=" + err.decode()[:2000])
    return out, err

def main():
    candidate = Path(sys.argv[1] if len(sys.argv) > 1 else "/workspace/project/campaign_cli.py")
    files = sorted(Path("/workspace/examples").glob("*.input.json"))
    passed = 0
    for path in files:
        try:
            out, err = run_child(candidate, path.read_bytes())
            actual = strict_json(out)
            if not isinstance(actual, dict):
                raise ValueError("output is not an object")
            expected = strict_json(path.with_name(path.name.replace(".input.", ".expected.")).read_bytes())
            if json.dumps(actual, sort_keys=True) != json.dumps(expected, sort_keys=True):
                raise ValueError("response differs:\n got " + json.dumps(actual, sort_keys=True) +
                                 "\nwant " + json.dumps(expected, sort_keys=True))
            passed += 1
            print("PASS " + path.name)
        except Exception as exc:
            print("FAIL " + path.name + ": " + str(exc))
    print(str(passed) + "/" + str(len(files)) + " local fixtures passed")
    return 0 if passed == len(files) else 1

if __name__ == "__main__":
    sys.exit(main())
